-- LABELXR-AGENT-BUDGET-RPC-v1
-- Only new permits one dispatch.Replay never permits another provider call.
-- Lost acknowledgements/failures consume reservations;no automatic refund.
BEGIN;
CREATE FUNCTION public.reserve_ai_budget(p_owner uuid,p_project uuid,p_turn uuid,p_base_revision integer,p_call_index integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' SET timezone='UTC' AS $$
DECLARE guest boolean;p public.projects;t public.agent_turns;user_budget public.daily_budget;global_budget public.daily_budget;utc_day date:=(now() AT TIME ZONE 'UTC')::date;reset_at timestamptz;cap integer;replay boolean:=false;
BEGIN
 IF p_owner IS NULL OR p_project IS NULL OR p_turn IS NULL OR p_base_revision IS NULL OR p_base_revision NOT BETWEEN 0 AND 300 OR p_call_index IS NULL OR p_call_index NOT BETWEEN 1 AND 3 THEN RAISE EXCEPTION 'Invalid budget request' USING ERRCODE='22023';END IF;
 -- Lock order:owner,project,global,user;compatible with project/review RPCs.
 SELECT is_anonymous INTO guest FROM auth.users WHERE id=p_owner FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Verified account required' USING ERRCODE='42501';END IF;SELECT * INTO p FROM public.projects WHERE id=p_project AND owner_id=p_owner FOR UPDATE;IF NOT FOUND OR p.status<>'ready' OR NOT p.ai_consent OR (p.kind='demo') IS DISTINCT FROM guest OR (guest AND p.expires_at<=now()) THEN RAISE EXCEPTION 'Owned live consenting project required' USING ERRCODE='42501';END IF;IF p.current_revision<>p_base_revision THEN RAISE EXCEPTION 'Stale agent revision' USING ERRCODE='40001';END IF;
 cap:=CASE WHEN guest THEN 3 ELSE 30 END;reset_at:=((utc_day+1)::timestamp AT TIME ZONE 'UTC');SELECT * INTO t FROM public.agent_turns WHERE owner_id=p_owner AND turn_id=p_turn FOR UPDATE;
 IF FOUND THEN IF t.project_id<>p_project OR t.base_revision<>p_base_revision OR (t.created_at AT TIME ZONE 'UTC')::date<>utc_day THEN RAISE EXCEPTION 'Turn UUID belongs to another context/day' USING ERRCODE='22023';END IF;IF p_call_index<=t.provider_calls THEN replay:=true;ELSIF p_call_index<>t.provider_calls+1 THEN RAISE EXCEPTION 'Provider calls must be reserved sequentially' USING ERRCODE='22023';END IF;ELSIF p_call_index<>1 THEN RAISE EXCEPTION 'First call index must be one' USING ERRCODE='22023';END IF;
 INSERT INTO public.daily_budget(day,scope,turns,provider_calls) VALUES(utc_day,'global',0,0) ON CONFLICT DO NOTHING;SELECT * INTO global_budget FROM public.daily_budget WHERE day=utc_day AND scope='global' FOR UPDATE;INSERT INTO public.daily_budget(day,scope,owner_id,turns,provider_calls) VALUES(utc_day,'user',p_owner,0,0) ON CONFLICT DO NOTHING;SELECT * INTO user_budget FROM public.daily_budget WHERE day=utc_day AND scope='user' AND owner_id=p_owner FOR UPDATE;
 IF NOT replay THEN IF global_budget.provider_calls>=300 OR (t.turn_id IS NULL AND user_budget.turns>=cap) THEN RAISE EXCEPTION 'AI budget exhausted' USING ERRCODE='23514';END IF;IF t.turn_id IS NULL THEN INSERT INTO public.agent_turns(owner_id,turn_id,project_id,base_revision,provider_calls) VALUES(p_owner,p_turn,p_project,p_base_revision,1);user_budget.turns:=user_budget.turns+1;ELSE UPDATE public.agent_turns SET provider_calls=provider_calls+1 WHERE owner_id=p_owner AND turn_id=p_turn;END IF;user_budget.provider_calls:=user_budget.provider_calls+1;global_budget.provider_calls:=global_budget.provider_calls+1;UPDATE public.daily_budget SET turns=user_budget.turns,provider_calls=user_budget.provider_calls WHERE day=utc_day AND scope='user' AND owner_id=p_owner;UPDATE public.daily_budget SET provider_calls=global_budget.provider_calls WHERE day=utc_day AND scope='global';END IF;
 RETURN jsonb_build_object('disposition',CASE WHEN replay THEN 'replay' ELSE 'new' END,'turnId',p_turn,'projectId',p_project,'baseRevision',p_base_revision,'callIndex',p_call_index,'day',utc_day,'resetAt',reset_at,'userTurns',user_budget.turns,'userLimit',cap,'globalCalls',global_budget.provider_calls,'globalLimit',300);END $$;
REVOKE ALL ON FUNCTION public.reserve_ai_budget(uuid,uuid,uuid,integer,integer) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.reserve_ai_budget(uuid,uuid,uuid,integer,integer) TO service_role;
COMMIT;
